#!/usr/bin/env python3
"""
Pages Batch 68 (Canvases 371-375, pp. 343-347) for Wellcome MS.244.
Covers five pages of the Main Compendium (Medical & Surgical Receipts):
  - Canvas 371 (p. 343): Scurvy ('Scorbutum') clysters, suppositories, and gum lotions; Latin fever juleps ('Julapium in febre ardenti') attributed to Dr. John Sadler ('D. S.')
  - Canvas 372 (p. 344): Scurvy beers, ales, and distilled waters ('Scorbye', 'ffor the Scorbutum')
  - Canvas 373 (p. 345): Green salves and oils ('The greene salue for all Soores', 'A greene oile', Henry Dingley's note on old vs. new herbs), wound inflammations, 'Unguentum Rosatum Refrigeratum', and 'Takings Red or White'
  - Canvas 374 (p. 346): Medicinal Oils ('Oiles': wheat, wheaten bread, violets for pleurisy, 'The Hermett oile' attributed to grandmother Elizabeth, juniper wood, earthworms, camomile, mint, roses, mastic, rue)
  - Canvas 375 (p. 347): Medicinal Oils & Balsams (wormwood, sage for palsy, 'Oile Salerne', castoreum, mastic, almonds, 'Oile of mace' by Lady Burges, and 'Lucatelle by the La. B. receypt' with Henry Dingley's proportion table)
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


